 const before=document.getElementById('screen').toDataURL(),catalog=await buildPedia();
 registerPediaTab(plus,{load:async()=>catalog,revealed:new Map()});plus.open();plus.selectTab('pedia');
 await new Promise(r=>setTimeout(r,100));let container=document.getElementById('por-plus-content');
