 await plus.setSetting('original',true);plus.selectTab('pedia');if(!container.textContent.includes('off in original-game mode'))throw Error('master switch failed');
 await plus.setSetting('original',false);plus.close();if(before!==document.getElementById('screen').toDataURL())throw Error('game canvas changed');
 return {pass:true,monsters:catalog.entries.filter(e=>e.kind==='monster').length,unseenHidden:true,search:true,entryLayout:true,canvasUnchanged:true};
})()
